const basketStorageKey='lepetse.catalogueBasket.v1';
let basketStorageUnavailable=false;
function restoreBasket(){try{const raw=JSON.parse(localStorage.getItem(basketStorageKey)||'[]');if(!Array.isArray(raw))return [];return raw.slice(0,250).flatMap(x=>{const p=products.find(p=>p.id===x.id);return p&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=999999?[{productId:p.id,description:`${p.name} — ${p.summary}`,quantity:x.quantity,unit:p.unit}]:[]})}catch{return []}}
function saveBasket(){try{const lines=items.filter(x=>products.some(p=>p.id===x.productId)).map(x=>({id:x.productId,quantity:Number(x.quantity)}));if(lines.length)localStorage.setItem(basketStorageKey,JSON.stringify(lines));else localStorage.removeItem(basketStorageKey)}catch{basketStorageUnavailable=true}}
function showAdded(p,quantity,total){const d=document.getElementById('basket-dialog');d.innerHTML=`<div class="confirmation-mark" aria-hidden="true">✓</div><h2 id="basket-dialog-title">Added to your quote basket</h2><p class="added-name">${esc(p.name)}</p><dl><div><dt>Quantity added</dt><dd>${quantity}</dd></div><div><dt>Ordering unit</dt><dd>${esc(p.unit)}</dd></div><div><dt>Now in your basket</dt><dd>${total} × ${esc(p.unit)}</dd></div></dl><div class="dialog-actions"><button class="btn outline" id="keep-browsing">Continue browsing</button><a class="btn dark" href="#basket" id="see-basket">View basket</a></div>`;d.showModal();$('#keep-browsing').onclick=()=>d.close();$('#see-basket').onclick=()=>d.close();$('#keep-browsing').focus()}
function clearBasketPrompt(){const d=document.getElementById('basket-dialog');d.innerHTML='<h2 id="basket-dialog-title">Clear your quote basket?</h2><p>This removes saved catalogue selections from this device. Contact details and attachments are separate.</p><div class="dialog-actions"><button class="btn outline" id="cancel-clear">Keep basket</button><button class="btn dark" id="confirm-clear">Clear basket</button></div>';d.showModal();$('#cancel-clear').onclick=()=>d.close();$('#confirm-clear').onclick=()=>{items=[];saveBasket();updateCount();d.close();main.innerHTML=basket();bindBasket();main.querySelector('h1')?.focus()};$('#cancel-clear').focus()}
const facetKeys={paper:['Size','Weight','Colour'],books:['Size','Pages','Sheets','Ruling','Binding'],pens:['Ink colour','Tip','Grade'],files:['Size','Spine width','Pockets','Material'],art:['Colours','Size','Type'],ruler:['Length','Material','Type'],calc:['Display','Type']};
function renderFacets(cat){const area=$('#category-facets');const pool=products.filter(p=>p.category===cat);const keys=(facetKeys[cat]||[]).filter(k=>pool.some(p=>p.specs[k]));area.innerHTML=keys.length?`<div class="facet-heading">Filter ${esc(categories.find(c=>c[2]===cat)[0].toLowerCase())}</div><div class="facet-grid">${keys.map((k,i)=>{const values=[...new Set(pool.map(p=>p.specs[k]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));return `<div><label for="facet-${i}">${esc(k==='Weight'?'Paper weight':k==='Pages'?'Page count':k)}</label><select id="facet-${i}" data-facet="${esc(k)}"><option value="">All</option>${values.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}</select></div>`}).join('')}</div>`:''}
function bindCatalogue(){$('#global-search').value=new URLSearchParams(location.hash.split('?')[1]||'').get('q')||'';function refresh(){const q=$('#global-search').value.trim().toLowerCase(),cat=$('#category-filter').value;const facets=[...main.querySelectorAll('[data-facet]')].filter(e=>e.value);let shown=products.filter(p=>(!cat||p.category===cat)&&facets.every(e=>p.specs[e.dataset.facet]===e.value)&&[p.name,p.summary,p.unit,JSON.stringify(p.specs),categories.find(c=>c[2]===p.category)[0]].join(' ').toLowerCase().includes(q));if($('#catalogue-sort').value==='name')shown.sort((a,b)=>a.name.localeCompare(b.name));$('#result-count').textContent=`${shown.length} product${shown.length===1?'':'s'}${q?' matching “'+q+'”':''}`;$('#product-results').innerHTML=shown.map(productCard).join('')||'<div class="empty"><h3>No products match these filters</h3><p>Remove a specification filter, choose another category or upload your list.</p><button class="btn outline" id="empty-reset">Clear filters</button></div>';$('#empty-reset')?.addEventListener('click',reset);bindProducts()}
function categoryChanged(){renderFacets($('#category-filter').value);main.querySelectorAll('[data-facet]').forEach(e=>e.onchange=refresh);refresh()}
function reset(){$('#global-search').value='';$('#category-filter').value='';$('#catalogue-sort').value='default';categoryChanged()}
$('#category-filter').onchange=categoryChanged;$('#catalogue-sort').onchange=refresh;$('#reset-filters').onclick=reset;main.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{$('#category-filter').value=b.dataset.filter;categoryChanged()});categoryChanged()}
let uploadDraft={},uploadFiles=[];
function uploadPage(){const v=(n)=>esc(uploadDraft[n]||'');return `${pageHero('Document enquiry','Upload your stationery list','Attach your document and complete the details below. No product entry is needed.')}<section class="section"><div class="wrap upload-layout"><form id="document-enquiry"><fieldset class="upload"><legend>Your documents *</legend><label for="document-files">Stationery list, school list or RFQ</label><input id="document-files" type="file" multiple accept=".pdf,.xlsx,.csv,.docx,.jpg,.jpeg,.png"><p class="help">Up to 5 files, 10 MB each. PDF, XLSX, CSV, DOCX, JPG or PNG. Attachments stay on your device.</p><p id="document-file-list">${uploadFiles.map(f=>esc(f.name)).join(', ')}</p><button type="button" class="clear-filters" id="remove-documents">Remove documents</button></fieldset><div class="fields">${[['organisation','Organisation','text',true],['contact','Contact person','text',true],['email','Email address','email',true],['phone','Telephone','tel',false],['town','Delivery town / city','text',true],['postcode','Postcode','text',true]].map(([n,l,t,req])=>`<div class="field"><label for="upload-${n}">${l}${req?' *':''}</label><input id="upload-${n}" name="${n}" type="${t}" value="${v(n)}" ${req?'required':''} ${n==='postcode'?'pattern="[0-9]{4}" title="Four-digit South African postcode"':''}></div>`).join('')}<div class="field"><label for="upload-province">Province *</label><select id="upload-province" name="province" required><option value="">Select a province</option>${['Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','North West','Northern Cape','Western Cape'].map(p=>`<option ${uploadDraft.province===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="field"><label for="upload-date">Required delivery date *</label><input id="upload-date" name="date" type="date" value="${v('date')}" required></div><div class="field"><label for="upload-reference">RFQ reference (if applicable)</label><input id="upload-reference" name="reference" value="${v('reference')}"></div><div class="field"><label for="upload-deadline">Quote closing deadline SAST (if applicable)</label><input id="upload-deadline" name="deadline" type="datetime-local" value="${v('deadline')}"></div><div class="field full"><label for="upload-notes">Delivery sites or additional instructions</label><textarea id="upload-notes" name="notes">${v('notes')}</textarea></div></div><p id="upload-error" class="error" role="alert"></p><button class="btn dark" type="submit">Review enquiry</button></form><aside><h2>Document-based request</h2><p>We’ll use the attached list as the specification. Existing quote-basket products are kept separate.</p><p class="help">Prototype: review and download your enquiry. It is not sent to Lepetse.</p></aside></div></section>`}
function captureUpload(){const f=$('#document-enquiry');if(f)new FormData(f).forEach((v,k)=>{if(typeof v==='string')uploadDraft[k]=v.trim()})}
function bindUpload(){const f=$('#document-enquiry');f.oninput=captureUpload;$('#document-files').onchange=e=>{const files=[...e.target.files];if(files.length>5||files.some(f=>f.size>10*1024*1024||!/\.(pdf|xlsx|csv|docx|jpe?g|png)$/i.test(f.name))){e.target.value='';$('#upload-error').textContent='Choose up to five supported files, each no larger than 10 MB.';return}uploadFiles=files;$('#document-file-list').textContent=files.map(f=>f.name).join(', ');$('#upload-error').textContent=''};$('#remove-documents').onclick=()=>{uploadFiles=[];$('#document-files').value='';$('#document-file-list').textContent=''};f.onsubmit=e=>{e.preventDefault();captureUpload();let err='';if(!uploadFiles.length)err='Attach at least one document before continuing.';else if(uploadDraft.date<new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}))err='Choose a current or future delivery date.';else if(uploadDraft.deadline&&new Date(uploadDraft.deadline+'+02:00')<new Date())err='The quote closing deadline has passed. Check the date and time.';$('#upload-error').textContent=err;if(err)return;showEnquiry({buyer:{...uploadDraft,buyerType:formData.buyerType||'Document enquiry'},items:[],attachments:uploadFiles.map(f=>({name:f.name,size:f.size}))},()=>{main.innerHTML=uploadPage();bindUpload()})}}
function enquiryDocument(s){const b=s.buyer;const field=(l,v)=>v?`<div><dt>${l}</dt><dd>${esc(v)}</dd></div>`:'';return `<article class="enquiry-document"><div class="document-heading"><strong>LEPETSE</strong><span>Prepared enquiry · not sent</span></div><h1>Stationery enquiry summary</h1><p class="document-date">Prepared ${new Date().toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'})} SAST</p><section><h2>Buyer and contact</h2><dl>${field('Organisation',b.organisation)}${field('Contact',b.contact)}${field('Email',b.email)}${field('Telephone',b.phone)}${field('Buyer type',b.buyerType)}${field('Order type',b.orderType)}</dl></section><section><h2>Delivery and timing</h2><dl>${field('Location',[b.town,b.province,b.postcode].filter(Boolean).join(', '))}${field('Number of sites',b.sites)}${field('Required date',b.date)}${field('Date flexibility',b.timing)}${field('RFQ reference',b.reference)}${field('Closing deadline',b.deadline?b.deadline.replace('T',' ')+' SAST':'')}${field('Submission channel',b.channel)}${field('Mandatory briefing',b.briefing)}</dl></section><section><h2>${s.items.length?'Item requirements':'Document requirements'}</h2>${s.items.length?`<div class="table-scroll"><table><thead><tr><th>Item description / specification</th><th>Quantity</th><th>Ordering unit</th></tr></thead><tbody>${s.items.map(x=>`<tr><td>${esc(x.description)}</td><td>${esc(x.quantity)}</td><td>${esc(x.unit)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Use the attached document list below as the item specification.</p>'}${b.alternatives?`<p>Alternatives: ${esc(b.alternatives)}</p>`:''}</section>${b.notes?`<section><h2>Additional instructions</h2><p class="preserve-lines">${esc(b.notes)}</p></section>`:''}<section><h2>Documents</h2>${s.attachments.length?`<ul>${s.attachments.map(f=>`<li>${esc(f.name)} (${Math.ceil(f.size/1024)} KB)</li>`).join('')}</ul><p>Original attachments are not embedded. Attach them separately when sharing this enquiry.</p>`:'<p>No documents attached.</p>'}</section><p class="document-disclaimer">This is a prepared request, not a quotation, purchase order or confirmation of stock. Prices, applicable VAT, delivery and payment terms require confirmation. Nothing has been sent to Lepetse.</p></article>`}
function showEnquiry(summary,onEdit){const doc=enquiryDocument(summary);main.innerHTML=`<section class="section summary-view"><div class="wrap"><div class="enquiry-actions"><div><h2>Review your enquiry</h2><p>Download a formatted copy or print it. You can save as PDF in the print dialog.</p></div><div><button class="btn dark" id="download-summary">Download enquiry</button><button class="btn outline" id="print-summary">Print / save as PDF</button><button class="btn outline" id="edit-summary">Edit details</button></div></div>${doc}</div></section>`;$('#edit-summary').onclick=onEdit;$('#print-summary').onclick=()=>window.print();$('#download-summary').onclick=()=>{const styles=document.getElementById('summary-styles').textContent;const html='<!doctype html><html lang="en-ZA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lepetse stationery enquiry</title><style>'+styles+'</style></head><body><div class="enquiry-actions standalone-actions"><button onclick="window.print()">Print / save as PDF</button></div>'+doc+'</body></html>';const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Lepetse-stationery-enquiry.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};main.focus();window.scrollTo(0,0)}
